{
  "version": 1,
  "hooks": {
    "beforeShellExecution": [
      {
        "command": "/opt/guard-runtime cursor-hook-bridge /usr/bin/python3 -I /home/user/.cursor/hooks/hol-guard-cursor-hook.py --cursor-hook-event beforeShellExecution",
        "timeout": 45,
        "failClosed": true
      }
    ],
    "beforeMCPExecution": [
      {
        "command": "/opt/guard-runtime cursor-hook-bridge /usr/bin/python3 -I /home/user/.cursor/hooks/hol-guard-cursor-hook.py --cursor-hook-event beforeMCPExecution",
        "timeout": 45,
        "failClosed": true
      }
    ],
    "beforeReadFile": [
      {
        "command": "/opt/guard-runtime cursor-hook-bridge /usr/bin/python3 -I /home/user/.cursor/hooks/hol-guard-cursor-hook.py --cursor-hook-event beforeReadFile",
        "timeout": 45,
        "failClosed": true
      }
    ],
    "preToolUse": [
      {
        "command": "/opt/guard-runtime cursor-hook-bridge /usr/bin/python3 -I /home/user/.cursor/hooks/hol-guard-cursor-hook.py --cursor-hook-event preToolUse",
        "timeout": 45,
        "failClosed": true,
        "matcher": "^(Write|Edit|StrReplace|MultiEdit|Delete|Shell)$"
